#!/usr/bin/env python3
"""Fill safety audit HWPX template (HWPML XML inside .hwpx).

Key requirements from task:
- Consolidate fragmented <hp:t> runs per paragraph before replacements.
- Replace all {{...}} placeholders using JSON data.
- Risk tier needs severity note appended (e.g., "High 즉시조치") for every occurrence.
- Inspection date must be YYYY.MM.DD everywhere.
- For every modified paragraph, remove any <hp:linesegarray> layout cache.
- Verify no '{{' remains.
"""

import json
import os
import re
import xml.etree.ElementTree as ET


HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NS = {"hp": HWPML_NS}


def qn(tag: str) -> str:
    """Qualified name helper for ElementTree."""
    prefix, local = tag.split(":", 1)
    if prefix != "hp":
        raise ValueError(f"Only hp: supported in qn(); got {tag}")
    return f"{{{HWPML_NS}}}{local}"


def load_json(path: str):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def date_yyyy_mm_dd_to_dotted(s: str) -> str:
    # Only transform if it matches the expected format.
    if isinstance(s, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
        return s.replace("-", ".")
    return s


def severity_note(risk_tier: str) -> str:
    mapping = {
        "High": "즉시조치",
        "Medium": "계획보완",
        "Low": "모니터링",
    }
    return mapping.get(risk_tier, "")


def build_replacements(overview: dict, actions: dict) -> dict:
    summary = overview.get("summary", {})

    repl = {}
    # Map all top-level summary keys to same placeholder names.
    for k, v in summary.items():
        repl[str(k)] = str(v)

    # Force date formatting for inspection date
    if "점검일" in repl:
        repl["점검일"] = str(date_yyyy_mm_dd_to_dotted(repl["점검일"]))

    # Risk tier with severity note appended
    risk = summary.get("위험등급", "")
    risk = str(risk)
    note = severity_note(risk)
    if risk and note:
        repl["위험등급"] = f"{risk} {note}"

    # Corrective actions in order
    immediate = actions.get("immediate_actions", [])
    for idx, item in enumerate(immediate[:3], start=1):
        repl[f"조치{idx}"] = str(item)

    return repl


def consolidate_runs_in_paragraph(p_elem: ET.Element) -> bool:
    """Consolidate all <hp:t> within a paragraph into the first <hp:t>.

    Returns True if any consolidation changed the paragraph text structure.
    """
    # Gather all text elements in document order under this paragraph.
    t_elems = list(p_elem.findall('.//hp:t', NS))
    if len(t_elems) <= 1:
        return False

    combined = "".join([(t.text or "") for t in t_elems])

    if (t_elems[0].text or "") == combined and all((t.text in (None, "")) for t in t_elems[1:]):
        return False

    # Put combined text in first element.
    t_elems[0].text = combined

    # Remove subsequent <hp:t> elements from their parent runs if possible.
    for t in t_elems[1:]:
        parent = None
        # ElementTree doesn't have getparent; we search for direct parent run.
        for run in p_elem.findall('.//hp:run', NS):
            for child in list(run):
                if child is t:
                    parent = run
                    break
            if parent is not None:
                break

        if parent is not None:
            # remove the t node
            try:
                parent.remove(t)
            except ValueError:
                pass
            # if run becomes empty, remove run
            if len(list(parent)) == 0:
                # find parent of run (likely paragraph)
                for maybe_parent in p_elem.iter():
                    for child in list(maybe_parent):
                        if child is parent:
                            try:
                                maybe_parent.remove(parent)
                            except ValueError:
                                pass
                            break
        else:
            # fallback: cannot locate parent; leave it
            pass

    return True


def replace_in_text(text: str, replacements: dict) -> str:
    if text is None:
        return text

    # Replace any {{key}} placeholders.
    def _sub(m):
        key = m.group(1)
        if key in replacements:
            return replacements[key]
        # If missing, keep placeholder as-is so we can warn later.
        return m.group(0)

    return re.sub(r"\{\{([^{}]+)\}\}", _sub, text)


def remove_linesegarray(p_elem: ET.Element):
    # remove namespaced and non-namespaced linesegarray directly under paragraph
    for child in list(p_elem):
        tag = child.tag
        if tag == qn('hp:linesegarray') or tag.endswith('linesegarray'):
            p_elem.remove(child)


def process_xml(xml_path: str, replacements: dict):
    parser = ET.XMLParser(encoding="utf-8")
    tree = ET.parse(xml_path, parser=parser)
    root = tree.getroot()

    modified_paragraphs = set()  # element ids (python id)

    # Consolidate runs first so placeholders aren't fragmented.
    for p in root.findall('.//hp:p', NS):
        if consolidate_runs_in_paragraph(p):
            modified_paragraphs.add(id(p))

    # Perform replacements in each text node.
    for p in root.findall('.//hp:p', NS):
        p_modified = False
        for t in p.findall('.//hp:t', NS):
            original = t.text or ""
            new = replace_in_text(original, replacements)
            if new != original:
                t.text = new
                p_modified = True

        if p_modified:
            modified_paragraphs.add(id(p))

    # Remove layout cache on modified paragraphs.
    for p in root.findall('.//hp:p', NS):
        if id(p) in modified_paragraphs:
            remove_linesegarray(p)

    # Write back.
    tree.write(xml_path, encoding="UTF-8", xml_declaration=True)

    # Verify no placeholders remain.
    leftover = []
    for t in root.findall('.//hp:t', NS):
        if t.text and "{{" in t.text:
            leftover.append(t.text)
    return leftover


def main():
    overview = load_json("/root/audit_overview.json")
    actions = load_json("/root/corrective_actions.json")
    replacements = build_replacements(overview, actions)

    contents_dir = "/tmp/hwpx_work/extracted/Contents"
    xml_files = [
        os.path.join(contents_dir, f)
        for f in os.listdir(contents_dir)
        if f.lower().endswith('.xml')
    ]

    all_leftover = {}
    for xml_path in sorted(xml_files):
        leftover = process_xml(xml_path, replacements)
        if leftover:
            all_leftover[xml_path] = leftover

    if all_leftover:
        print("WARNING: Unreplaced placeholders remain:")
        for path, items in all_leftover.items():
            print(f"- {path}:")
            for s in items:
                print(f"  {s}")
    else:
        print("OK: No '{{' placeholders remain in processed XML files.")


if __name__ == "__main__":
    main()

